const ELEMENT_PROP_KEYS = new Set(["theme","accent","split","radius","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  split: 22,
  radius: 6,
  fontFamily: "Schibsted Grotesk",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type TreemapSplitElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof TreemapSplitBase>;

const TreemapSplitInner = forwardRef<
  HTMLDivElement,
  TreemapSplitElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<TreemapSplit>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <TreemapSplitBase
          {...(componentProps as unknown as ComponentProps<typeof TreemapSplitBase>)}
        />
      </div>
    </Sequence>
  );
});

export const TreemapSplit = Interactive.withSchema({
  Component: TreemapSplitInner,
  componentName: "<TreemapSplit>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
